pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint8 v, uint8 _decimals) public {
        // 1. Admissible domain: avoid arithmetic overflow in _value computation and ensure non-empty array.
        vm.assume(v < 2);
        vm.assume(_decimals < 20);
        vm.assume(_tos.length > 0);
        // 2. Deploy a helper that always succeeds when called with any calldata (no revert).
        Successor helper = new Successor();
        caddress = address(helper);
        // 3. The call never reverts because helper accepts everything. Reference always returns true; mutant returns false.
        bool ok = c.transfer(from, caddress, _tos, v, _decimals);
        assertTrue(ok);
    }
}

contract Successor {
    fallback() external payable {
        // do nothing, always succeed
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] calldata _tos, uint v, uint _decimals) public {
        vm.assume(_tos.length > 0);
        vm.assume(caddress != address(0));
        vm.assume(caddress != address(this));
        vm.assume(caddress != address(c));
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
            vm.assume(_tos[i] != caddress);
        }
        (bool success, bytes memory ret) = address(c).call(abi.encodeWithSignature("transfer(address,address,address[],uint256,uint256)", from, caddress, _tos, v, _decimals));
        assertTrue(success && (ret.length >= 32) && (abi.decode(ret, (bool)) == true));
    }
}

