pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract Caller {
    function callTransfer(C _c, address from, address caddress, address[] memory _tos, uint v, uint _decimals) external returns (bool) {
        try _c.transfer(from, caddress, _tos, v, _decimals) returns (bool ret) {
            return ret;
        } catch {
            return false;
        }
    }
}

contract InvMutTest is Test {
    C c;
    Caller caller;

    function setUp() public {
        c = new C();
        caller = new Caller();
    }

    function testFuzz_property(
        address from,
        address caddress,
        address[] memory _tos,
        uint256 v,
        uint256 _decimals
    ) public {
        // Restrict the admitible domain to avoid revert due to overflow or empty array.
        // The reference requires _tos.length > 0, and the calculation v * 10**_decimals may overflow.
        vm.assume(_tos.length > 0);
        // Bound decimals to a small range to keep the domain wide and avoid overflow in 10**_decimals.
        _decimals = bound(_decimals, 0, 18);
        // Bound v so that v * 10**_decimals does not overflow uint256.
        v = bound(v, 0, type(uint256).max / (10 ** _decimals));

        // The call must not revert. We perform a low-level call to observe revert only.
        (bool success, ) = address(c).call(
            abi.encodeWithSelector(c.transfer.selector, from, caddress, _tos, v, _decimals)
        );
        vm.assume(success);

        // For any non-reverting call, the high-level return value must be true.
        bool ret = caller.callTransfer(c, from, caddress, _tos, v, _decimals);
        assertTrue(ret);
    }
}
